// ── Modul 2 · Eingangs-Guards ─────────────────────────────────────────────
// Prueft die Pflichtfelder aus dem Airtable-Formular, bevor irgendein
// externer Call passiert. Faellt hier etwas durch, geht GATE 1 in den
// Fehlerpfad und es wird nichts geschrieben.

const s = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const list = (v) => s(v).split('|').map((x) => x.trim()).filter(Boolean);

const recordId = s(input.recordId);
const name     = s(input.name);
const plzRaw   = s(input.plz);
const strasse  = s(input.strasse);
// ── Bild ─────────────────────────────────────────────────────────────────
// Stellschrauben. MIN_BREITE ist eine reine Empfehlung (Meldung, kein Stopp);
// zu klein kann Shopify nicht heilen, zu gross schon (image_url skaliert).
const MIN_BREITE = 1200;
const OK_TYPES   = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];

const num = (v) => {
  const n = parseInt(String(v === null || v === undefined ? '' : v)
                       .replace(/[^0-9]/g, ''), 10);
  return isNaN(n) ? 0 : n;
};

// Airtable legt zu jedem erkannten Bild-Attachment eigene Thumbnails an, und
// die sind immer JPEG/PNG — auch wenn das Original HEIC ist (iPhone-Standard),
// das Shopifys fileCreate nicht annimmt. thumbnails.full hat deshalb Vorrang
// vor der Originaldatei: der Vertriebler laedt hoch, was seine Kamera macht,
// und muss nichts umstellen. full ist bei Airtable auf 3000 px gedeckelt und
// bei kleineren Bildern identisch zum Original — als 16:9-Teaser reicht das.
// Fehlt der Thumbnail (Airtable erzeugt ihn nur fuer erkannte Bildformate),
// faellt die Quelle aufs Original zurueck und der Formatcheck unten greift.
const bildOriginal  = s(input.bildUrl);
const bildThumb     = s(input.bildThumbUrl);
const bildTyp       = s(input.bildType).toLowerCase();
const nutztThumb    = bildThumb !== '';

const bildUrl    = nutztThumb ? bildThumb : bildOriginal;
const bildBreite = nutztThumb ? (num(input.bildThumbWidth)  || num(input.bildWidth))
                              : num(input.bildWidth);
const bildHoehe  = nutztThumb ? (num(input.bildThumbHeight) || num(input.bildHeight))
                              : num(input.bildHeight);

const sortiment    = list(input.sortiment);
const paketdienste = list(input.paketdienste);

// PLZ: Airtable haelt eine Zahl -> fuehrende Null geht verloren (01067).
// plz5 ist die 5-stellige Vergleichsform, plzInt der Wert fuer Shopify.
const plzDigits = plzRaw.replace(/[^0-9]/g, '');
const plz5      = plzDigits ? plzDigits.padStart(5, '0') : '';
const plzInt    = plzDigits ? parseInt(plzDigits, 10) : 0;

// Hausnummer aus "Musterstrasse 12a" / "Musterstr. 12-14"
const hnMatch    = strasse.match(/(\d+\s*[a-zA-Z]?(?:\s*[-\/]\s*\d+\s*[a-zA-Z]?)?)\s*$/);
const hausnummer = hnMatch ? hnMatch[1].replace(/\s+/g, '') : '';

const missing = [];
if (!name)               missing.push('Name');
if (!plz5)               missing.push('Postleitzahl');
if (plzInt < 1 || plzInt > 99999) missing.push('Postleitzahl (nicht 1-99999)');
if (!strasse)            missing.push('Straße / Nr.');
if (!hausnummer)         missing.push('Hausnummer in Straße / Nr.');
if (!bildUrl)            missing.push('Bild');
// Nur relevant, wenn kein Thumbnail da ist — dann geht das Original direkt an
// fileCreate und muss ein Format sein, das Shopify annimmt. Mit Thumbnail ist
// die Frage erledigt, egal was das Original war. Das blockiert bewusst statt
// nur zu melden: ein nicht annehmbares Format laesst Modul 19 ohnehin
// scheitern, dann lieber hier — bevor irgendetwas geschrieben wurde.
if (bildUrl && !nutztThumb && bildTyp && OK_TYPES.indexOf(bildTyp) < 0) {
  missing.push('Bild-Dateiformat (' + bildTyp + ' kann nicht verarbeitet werden)');
}
if (!sortiment.length)   missing.push('Sortiment');

// Weiche Hinweise: sie blockieren NICHT. Der Store wird angelegt, die Zeile
// landet in der Status-Meldung an Operations. Bewusst so, weil beides
// Qualitaetsfragen sind und keine technischen Blocker — und weil der
// Vertriebler vor Ort nichts davon nachbessern kann.
const hinweise = [];
if (bildBreite && bildBreite < MIN_BREITE) {
  hinweise.push('Bild ist mit ' + bildBreite + ' px schmal (empfohlen ab ' +
                MIN_BREITE + ' px) — der Teaser wirkt unscharf.');
}
// Das Theme rendert den Teaser mit object-fit: cover auf 16:9. Querformat
// verliert oben und unten je rund 12 %, Hochformat ueber die Haelfte — und
// zwar meist genau den Teil mit dem Ladenschild.
if (bildBreite && bildHoehe && bildHoehe > bildBreite) {
  hinweise.push('Bild ist im Hochformat (' + bildBreite + '×' + bildHoehe +
                ') — der 16:9-Teaser schneidet den grössten Teil weg.');
}

const ok = missing.length === 0;

return {
  ok: ok,
  gate: ok ? 'go' : 'stop',
  reason: ok ? '' : 'Pflichtfelder fehlen oder sind unvollständig: ' + missing.join(', ') + '.',
  recordId: recordId,
  name: name,
  plz5: plz5,
  plzInt: plzInt,
  strasse: strasse,
  hausnummer: hausnummer,
  bildUrl: bildUrl,
  bildQuelle: nutztThumb ? 'thumbnail' : 'original',
  bildBreite: bildBreite,
  bildHoehe: bildHoehe,
  bildHinweise: hinweise.join(' '),
  sortiment: sortiment,
  paketdienste: paketdienste,
  telefon: s(input.telefon),
  whatsapp: s(input.whatsapp),
  instagram: s(input.instagram),
  facebook: s(input.facebook),
  tiktok: s(input.tiktok),
  webseite: s(input.webseite),
  textQuery: [name, strasse, plz5, 'Deutschland'].filter(Boolean).join(', ')
};

// ── Modul 5 · Places-Treffer verifizieren ────────────────────────────────
// Nimmt nur einen Treffer an, dessen PLZ UND Hausnummer mit der Eingabe
// übereinstimmen. Sonst fail-closed -> GATE 2 geht in den Fehlerpfad.

const parse = (v) => (typeof v === 'string' ? (v ? JSON.parse(v) : []) : (v || []));

const places = parse(input.places);
const plz5   = String(input.plz5 || '');
const hnIn   = String(input.hausnummer || '').toLowerCase().replace(/[^0-9a-z]/g, '');

const comp = (p, type) => {
  const arr = (p.addressComponents || []).filter(
    (c) => (c.types || []).indexOf(type) >= 0
  );
  if (!arr.length) return '';
  return String(arr[0].longText || arr[0].shortText || '');
};

const digits = (v) => String(v || '').replace(/[^0-9]/g, '');

const candidates = [];
let hit = null;

for (let i = 0; i < places.length; i++) {
  const p = places[i];
  const pPlz = digits(comp(p, 'postal_code'));
  const pHnR = comp(p, 'street_number');
  const pHn  = String(pHnR).toLowerCase().replace(/[^0-9a-z]/g, '');

  candidates.push((p.formattedAddress || '(ohne Adresse)'));

  if (!pPlz || pPlz !== plz5) continue;
  if (!pHn) continue;
  // exakt gleich ODER gleiche Hausnummer ohne Zusatz (12a == 12)
  if (pHn !== hnIn && digits(pHn) !== digits(hnIn)) continue;

  hit = p;
  break;
}

if (!hit) {
  return {
    ok: false,
    gate: 'stop',
    placeId: '',
    reason:
      'Google Places liefert keinen Treffer, bei dem PLZ (' + plz5 +
      ') UND Hausnummer (' + hnIn + ') mit der Eingabe übereinstimmen. ' +
      'Geprüft wurden: ' + (candidates.length ? candidates.join(' | ') : 'keine Ergebnisse') + '.'
  };
}

return {
  ok: true,
  gate: 'go',
  reason: '',
  placeId: String(hit.id || ''),
  displayName: (hit.displayName && hit.displayName.text) ? String(hit.displayName.text) : ''
};

// ── Modul 10 · Ortsbezug ─────────────────────────────────────────────────
// Zieht die Stadt (locality) aus den Google-Places-Details und den Stadtteil
// aus dem LocationIQ-Reverse-Geocoding (Modul 9). Liefert zusaetzlich die
// escapten Werte fuer die filterByFormula-Aufrufe der beiden folgenden
// Airtable-Module.
//
// Stadtteil-Schluessel in dieser Reihenfolge: suburb -> quarter -> neighbourhood.
// city_district und borough sind BEWUSST kein Fallback: das ist die
// Stadtbezirks-Ebene (OSM admin_level 9), liftr_district fuehrt Stadtteile
// (admin_level 10). Ein Stadtbezirk waere ein wohlgeformter falscher Wert.
//
// Modul 9 ist LocationIQ makeAPICall auf /v1/reverse. Uebergeben wird der
// volle body; der Parser ist tolerant und akzeptiert sowohl den ganzen Body
// (nimmt dann .address) als auch ein bereits ausgepacktes address-Objekt.

const parse = (v) => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);

const details = parse(input.details) || {};

// NFC -> casefold -> Umlaut-/ss-Faltung -> '-', '–' und Whitespace zu einem
// Leerzeichen -> trim. Identisch zu norm() in Modul 17.
const norm = (v) =>
  String(v || '').normalize('NFC').toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[-\u2013\s]+/g, ' ').trim();

// Identisch zu slug() in Modul 17. Bindestrich UND Leerzeichen werden beide
// zu '-', deshalb liefern "Linden-Nord" und "Linden Nord" denselben Handle.
const slug = (v) =>
  String(v || '').normalize('NFC').toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const pick = (components, type, longKey, typeKey) => {
  const arr = (components || []).filter(
    (c) => (c[typeKey] || []).indexOf(type) >= 0
  );
  return arr.length ? String(arr[0][longKey] || '') : '';
};

// Stadt aus Places-Details (addressComponents: longText / types)
const dc = details.addressComponents || [];
const locality =
  pick(dc, 'locality', 'longText', 'types') ||
  pick(dc, 'postal_town', 'longText', 'types') ||
  pick(dc, 'administrative_area_level_3', 'longText', 'types');

// ── Stadtteil aus LocationIQ (Modul 9) ───────────────────────────────────
const rev  = parse(input.rev) || {};
const addr = (rev && typeof rev === 'object' && rev.address) ? rev.address : rev;
const display = String(input.revDisplay || '').trim();

const hasAddr = !!addr && typeof addr === 'object' && !Array.isArray(addr) &&
                Object.keys(addr).length > 0;
const cc = String((addr && addr.country_code) || '').toLowerCase();

let district       = '';
let districtSource = '';
let revReason      = '';

if (!hasAddr) {
  // Eigene, von "kein Stadtteil gefunden" klar unterscheidbare Meldung.
  revReason =
    'LocationIQ hat keine verwertbare Adressstruktur geliefert (address-Objekt ' +
    'leer oder unerwartetes Antwortformat)' +
    (display ? '. Gemeldeter Ort: ' + display : '') + '.';
} else if (cc !== 'de') {
  revReason =
    'LocationIQ verortet diese Koordinaten nicht in Deutschland (country_code: ' +
    (cc || 'fehlt') + ')' + (display ? '. Gemeldeter Ort: ' + display : '') + '.';
} else {
  const keys = ['suburb', 'quarter', 'neighbourhood'];
  for (let i = 0; i < keys.length && !district; i++) {
    const v = String(addr[keys[i]] || '').trim();
    if (!v) continue;
    // Ein Wert, der nur die Stadt wiederholt, ist kein Stadtteil.
    if (norm(v) === norm(locality)) continue;
    district       = v;
    districtSource = keys[i];
  }
}

// Airtable-Formeln arbeiten mit Feldnamen und einfachen Anfuehrungszeichen.
const esc = (v) => String(v || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");

// ── Abfragen fuer Modul 16 (Airtable) und Modul 12 (Shopify) ─────────────
// Beide holen ab jetzt gezielt den EINEN gesuchten Stadtteil statt einer
// ganzen Liste. Damit ist Paginierung strukturell unmoeglich statt
// nachgeruestet — in Make waere sie teuer, weil ein blockierender Filter den
// kompletten Pfad ueberspringt und bedingte "Seite 2"-Module deshalb
// ausscheiden.
//
// Airtable: die Faltung aus norm() wird in der Formel nachgebaut. Zwei
// bewusste Luecken gegenueber norm(): keine NFC-Normalisierung und kein
// Kollaps von Mehrfach-Leerzeichen. Beides ist in Stadtteilnamen nicht
// belegt; greift die Formel doch einmal zu eng, faellt der Treffer aus und
// Modul 39 legte eine Dublette an — deshalb filtert Modul 17 die Rueckgabe
// zusaetzlich mit dem echten norm() nach.
const atFold = (field) =>
  'TRIM(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(' +
  'LOWER(' + field + '),"ä","ae"),"ö","oe"),"ü","ue"),"ß","ss"),"-"," "),"–"," "))';

const formulaDistricts = district
  ? "AND({Stadt} = '" + esc(locality) + "', " +
    atFold('{Name}') + " = '" + esc(norm(district)) + "')"
  : 'FALSE()';

// Shopify: drei Kandidaten in einer Abfrage. Die beiden handle-Zweige sind
// deterministisch und ASCII — der alte, stadtlose Handle (Bestand) und der
// neue stadtscoped Handle. display_name faengt zusaetzlich Bezirke ab, deren
// Handle von slug() abweicht (manuell angelegt oder von Shopify mit Suffix
// vergeben). Werte in Anfuehrungszeichen, sonst liest die Shopify-Suchsyntax
// den Bindestrich als NOT-Operator.
const shopDistrictQuery = district
  ? "handle:'" + slug(district) + "' OR handle:'" +
    slug(locality) + '-' + slug(district) + "' OR display_name:'" +
    esc(district) + "'"
  : "handle:'__kein_stadtteil__'";

const ok = !!locality && !revReason;
const reason = !locality
  ? 'Google Places liefert zu dieser Adresse keine Stadt (locality).'
  : revReason;

return {
  ok: ok,
  gate: ok ? 'go' : 'stop',
  reason: reason,
  locality: locality,
  localityEsc: esc(locality),
  district: district,
  districtSource: districtSource,
  formulaCity: "{Name} = '" + esc(locality) + "'",
  formulaDistricts: formulaDistricts,
  shopDistrictQuery: shopDistrictQuery
};

