mapper.codeEditorJavascript:
// ── Modul 17 · Auflösung + komplettes Mapping ────────────────────────────
// Letzte Stufe von Phase A. Loest Stadt, Stadtteil, Sortiment und Services
// gegen die gelesenen Bestaende auf und baut alle Nutzlasten fuer Phase B.
// Jede nicht aufloesbare Zuordnung ist fail-closed -> GATE 3 -> Fehlerpfad.

const parse = (v) => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);

const g      = parse(input.g) || {};
const P      = parse(input.place) || {};
const nearby = parse(input.nearby) || [];
const geo    = parse(input.geo) || {};

const mo = (v) => {
  const x = parse(v) || {};
  return { nodes: x.nodes || [], more: !!(x.pageInfo && x.pageInfo.hasNextPage) };
};
const shopCity       = mo(input.shopCity);
const shopDistrict   = mo(input.shopDistrict);
const shopService    = mo(input.shopService);
const shopAssortment = mo(input.shopAssortment);

const atCity      = parse(input.atCity) || [];
const atDistricts = parse(input.atDistricts) || [];

// Feld-IDs Airtable
const F_STADT_NAME   = 'fldD5NSzJjupX7waM';
const F_STADT_TG     = 'fldl5GAsDGTHl8iHL';
const F_TEIL_NAME    = 'fldNJ60R7UN2vNtJ5';
const F_TEIL_STADT   = 'fld3aeuw7c8wxXnMg';

const fail = (r) => ({ ok: false, gate: 'stop', reason: r });

// ── Helfer ───────────────────────────────────────────────────────────────
// NFC -> casefold -> Umlaut-/ss-Faltung -> Folgen aus '-', '–' und Whitespace
// zu einem Leerzeichen -> trim. Die Faltung faengt "Groß-Buchholz" vs
// "Gross-Buchholz". Identisch zu norm() in Modul 10.
const norm = (v) =>
  String(v || '').normalize('NFC').toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[-\u2013\s]+/g, ' ').trim();

const slug = (v) =>
  String(v || '').normalize('NFC').toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const isTrue = (v) => v === true;

// ── 0 · Vorstufe ─────────────────────────────────────────────────────────
if (!geo.ok) return fail(geo.reason || 'Ortsbezug konnte nicht aufgelöst werden.');

const locality = String(geo.locality || '');
const distName = String(geo.district || '');

if (!distName) {
  return fail(
    'LocationIQ liefert zu dieser Adresse keinen Stadtteil ' +
    '(suburb/quarter/neighbourhood). Der Stadtteil ist Pflichtfeld und wird ' +
    'nicht automatisch angelegt.'
  );
}

// ── 1 · Stadt in Airtable ────────────────────────────────────────────────
const cityRec = atCity.filter(
  (r) => String((r.fields || {})[F_STADT_NAME] || '') === locality
)[0];
if (!cityRec) {
  return fail(
    'Die Stadt "' + locality + '" existiert nicht zeichengenau in der Airtable-Tabelle ' +
    'Städte. Städte werden nicht automatisch angelegt (ohne Telegram-ID kein City-Channel).'
  );
}
const cityRecordId = String(cityRec.id || '');
const cityChatId   = String((cityRec.fields || {})[F_STADT_TG] || '').trim();

// ── 2 · Stadtteil in Airtable (find-or-create) ───────────────────────────
// Fehlt der Stadtteil, wird er NICHT mehr abgelehnt, sondern in Modul 39
// angelegt. Modul 17 entscheidet hier nur ueber method und url — der Write
// selbst sitzt bewusst spaeter, hinter der letzten Abbruchmoeglichkeit.
// Modul 16 sucht seit der Umstellung gezielt diesen einen Stadtteil (Stadt +
// gefalteter Name) statt alle Stadtteile der Stadt zu lesen. Der Nachfilter
// mit dem echten norm() bleibt trotzdem: er korrigiert eine Formel, die zu
// weit greift. Greift sie zu eng, kommt gar nichts zurueck — dann legt Modul
// 39 eine Dublette an. Das ist das einzige Restrisiko der Umstellung und der
// Grund, warum die Faltung in beiden Sprachen identisch bleiben muss.
const distMatches = atDistricts.filter(
  (r) => norm((r.fields || {})[F_TEIL_NAME]) === norm(distName)
);
if (distMatches.length > 1) {
  return fail(
    'In Airtable stehen mehrere Stadtteile, die auf "' + distName + '" in ' +
    locality + ' passen. Das ist eine Dublette in der Tabelle Stadtteile — ' +
    'es wurde nichts angelegt, bitte den Bestand bereinigen.'
  );
}
const distRec = distMatches[0];

const districtExistedAt    = !!distRec;
const districtRecordId     = distRec ? String(distRec.id || '') : '';
// Bestand schlaegt Zug: einen vorhandenen Namen nie mit der Geocoder-
// Schreibweise ueberschreiben ("Linden-Nord" bleibt "Linden-Nord").
const districtAirtableName = distRec
  ? String((distRec.fields || {})[F_TEIL_NAME] || distName)
  : distName;

const atBase  = String(input.atBase || '');
const atTeile = String(input.atTeile || '');
if (!atBase || !atTeile) {
  return fail('Interner Fehler: Base- oder Tabellen-ID fuer die Stadtteile fehlt.');
}
const districtApiMethod = districtExistedAt ? 'PATCH' : 'POST';
const districtApiUrl    = 'v0/' + atBase + '/' + atTeile +
                          (districtExistedAt ? '/' + districtRecordId : '');

// Der Body geht als fertiger JSON-STRING raus. Das body-Feld von
// airtable:makeApiCall hat den Typ 'any'; eine verschachtelte Collection
// reicht Make nicht als JSON hinaus, Airtable antwortet dann mit
// 422 "Could not parse request body". JSON.stringify escapt zugleich
// Sonderzeichen in Stadtteilnamen korrekt.
const districtApiFields = {};
districtApiFields[F_TEIL_NAME]  = districtAirtableName;
districtApiFields[F_TEIL_STADT] = [cityRecordId];
const districtApiBody = JSON.stringify({ fields: districtApiFields });

// ── 3 · liftr_city in Shopify ────────────────────────────────────────────
const cityNode = shopCity.nodes.filter(
  (n) => String(n.displayName || '') === locality
)[0];
if (!cityNode) {
  if (shopCity.more) {
    return fail('liftr_city: mehr als 250 Einträge vorhanden, "' + locality +
                '" war nicht auf der ersten Seite. Seitenlimit im Szenario anheben.');
  }
  return fail('Kein liftr_city-Metaobjekt mit displayName "' + locality + '" in Shopify gefunden.');
}
const cityGid = String(cityNode.id || '');

// ── 4 · liftr_district in Shopify (find-or-create) ───────────────────────
// Der Match laeuft ueber Name UND Stadt. Ohne den Stadtbezug trifft "Mitte"
// aus Hannover auch fuer Berlin zu, und der Upsert unten schriebe dann die
// Berliner city-Referenz in Hannovers Bezirk — ohne Fehler, ohne Guard.
const cityOf = (n) => String((n && n.city && n.city.value) || '');
const distNode = shopDistrict.nodes.filter(
  (n) => norm(n.displayName) === norm(districtAirtableName) &&
         cityOf(n) === cityGid
)[0];
if (!distNode && shopDistrict.more) {
  return fail('liftr_district: die Suche nach "' + districtAirtableName +
              '" liefert mehr als 25 Kandidaten. Das ist unerwartet — bitte den ' +
              'Bestand pruefen, bevor hier etwas angelegt wird.');
}
// Der Handle ist der Schluessel des Upserts und muss deshalb dieselbe
// Eindeutigkeit tragen wie der Match. Bestand behaelt seinen Handle (auch den
// alten, stadtlosen); Neuanlagen bekommen Stadt + Stadtteil. slug() faltet
// Umlaute und macht aus Bindestrich wie Leerzeichen ein '-', deshalb liefert
// es hier denselben Wert wie das slug() in Modul 10, das den Handle-Kandidaten
// fuer die Suche gebaut hat.
const districtHandle = distNode
  ? String(distNode.handle || '')
  : slug(locality) + '-' + slug(districtAirtableName);
// Bestehenden Anzeigenamen nicht ueberschreiben.
const districtDisplayName = distNode ? String(distNode.displayName || districtAirtableName)
                                     : districtAirtableName;
const districtExisted = !!distNode;

// ── 5 · Sortiment (displayName -> GID, zeichengenau) ─────────────────────
const assortmentGids = [];
for (let i = 0; i < g.sortiment.length; i++) {
  const wanted = String(g.sortiment[i]);
  const node = shopAssortment.nodes.filter((n) => String(n.displayName || '') === wanted)[0];
  if (!node) {
    return fail('Sortiment-Option "' + wanted + '" hat kein liftr_assortment-Metaobjekt ' +
                'mit zeichengenau gleichem displayName in Shopify.');
  }
  assortmentGids.push(String(node.id));
}
if (!assortmentGids.length) return fail('Sortiment ist leer — assortment_list ist Pflichtfeld.');

// ── 6 · Services (Handle -> GID) ─────────────────────────────────────────
const po = P.paymentOptions || {};
const pk = P.parkingOptions || {};
const ao = P.accessibilityOptions || {};

const svcHandles = [];
const addSvc = (handle, cond) => { if (isTrue(cond)) svcHandles.push(handle); };

addSvc('zahlen-mit-kreditkarte', po.acceptsCreditCards);
addSvc('mobil-zahlen-mit-nfc', po.acceptsNfc);
addSvc('barzahlung-moeglich', po.acceptsCashOnly);
addSvc('parkplaetze-an-der-strasse-kostenlos', pk.freeStreetParking);
addSvc('parkplaetze-an-der-strasse-gebuehrenpflichtig', pk.paidStreetParking);
addSvc('hunde-erlaubt', P.allowsDogs);
addSvc('rollstuhlgerechter-eingang', ao.wheelchairAccessibleEntrance);
addSvc('rollstuhlgerechter-parkplatz', ao.wheelchairAccessibleParking);
addSvc('rollstuhlgerechte-sitzgelegenheiten', ao.wheelchairAccessibleSeating);

// 'lieferung-moeglich' entfernt — das liftr_service ist deprecated.

if (nearby.length > 0) svcHandles.push('haltestelle-in-der-naehe-oepnv');
if (g.paketdienste.length > 0) svcHandles.push('paketannahme-moeglich');

const serviceGids = [];
for (let i = 0; i < svcHandles.length; i++) {
  const h = svcHandles[i];
  const node = shopService.nodes.filter((n) => String(n.handle || '') === h)[0];
  if (!node) return fail('Service-Handle "' + h + '" existiert nicht als liftr_service in Shopify.');
  serviceGids.push(String(node.id));
}

// ── 7 · Highlights (drei Slots, feste Reihenfolge) ───────────────────────
// Slot 1 — nie leer
let h1;
if (isTrue(po.acceptsCashOnly)) h1 = 'Nur Barzahlung';
else if (isTrue(po.acceptsCreditCards) || isTrue(po.acceptsDebitCards)) h1 = 'Barzahlung & Karte';
else h1 = 'Barzahlung';

// Slot 2 — aus regular.periods, ausschliesslich ueber day gruppiert
const regular = (P.regularOpeningHours && P.regularOpeningHours.periods) || [];
let alwaysOpen = false;
let lateClose  = false;
const daysOpen = {};
const markDay = (d) => { daysOpen[d] = true; };

for (let i = 0; i < regular.length; i++) {
  const p = regular[i];
  if (!p.open) continue;
  if (!p.close) { alwaysOpen = true; for (let d = 0; d < 7; d++) markDay(d); continue; }
  const od = p.open.day;
  markDay(od);
  if (p.close.day !== od) {
    // Mitternachts-Wrap: deckt jeden Tag bis close.day ab und gilt als "nach 22:00"
    lateClose = true;
    let d = od;
    for (let k = 0; k < 7; k++) {
      markDay(d);
      if (d === p.close.day) break;
      d = (d + 1) % 7;
    }
  } else {
    const ch = p.close.hour || 0;
    const cm = p.close.minute || 0;
    if (ch > 22 || (ch === 22 && cm > 0)) lateClose = true;
  }
}
const dayCount = Object.keys(daysOpen).length;

let h2 = '';
if (alwaysOpen && dayCount === 7) h2 = '24/7 geöffnet';
else if (dayCount === 7)          h2 = 'Täglich geöffnet';
else if (lateClose)               h2 = 'Lange geöffnet';

// Slot 3 — Paketshop, feste Carrier-Sortierung.
// 'Lieferung möglich' entfernt — die delivery-Quelle ist deprecated.
const CARRIER_ORDER = ['DHL', 'Hermes', 'DPD', 'GLS', 'UPS'];
let h3 = '';
{
  const named = CARRIER_ORDER.filter((c) => g.paketdienste.indexOf(c) >= 0);
  const hasOther = g.paketdienste.indexOf('Andere') >= 0;
  const total = named.length + (hasOther ? 1 : 0);
  if (total >= 3)                     h3 = 'Paketannahme';
  else if (named.length === 2)        h3 = named[0] + ' & ' + named[1] + ' Paketshop';
  else if (named.length === 1)        h3 = named[0] + ' Paketshop';   // "Andere" wird nicht benannt
  else if (hasOther)                  h3 = 'Paketannahme';
}

const highlights = [h1, h2, h3].filter(Boolean).slice(0, 3);

// ── 8 · Oeffnungszeiten / Bewertung / google_place ───────────────────────
const hasRegular = regular.length > 0;
const openingHours = hasRegular
  ? { regular: P.regularOpeningHours || null, current: P.currentOpeningHours || null }
  : { regular: null, current: null };

const ratingVal   = (typeof P.rating === 'number') ? P.rating : null;
const ratingCount = (typeof P.userRatingCount === 'number') ? P.userRatingCount : 0;
const writeRating = ratingVal !== null && ratingCount >= 1;

const placeDisplayName = (P.displayName && P.displayName.text) ? String(P.displayName.text) : g.name;
const loc = P.location || {};

// adress (Schema-Key mit EINEM d) traegt NUR Strasse + Hausnummer, so wie der
// gesamte Bestand: "Philipsbornstraße 24", "Grazer Str. 2". NICHT die
// formattedAddress — die enthaelt zusaetzlich PLZ, Stadt und teils den
// Stadtbezirk ("… 30179 Hannover-Bothfeld-Vahrenheide").
const comp = (type) => {
  const arr = (P.addressComponents || []).filter(
    (c) => (c.types || []).indexOf(type) >= 0
  );
  return arr.length ? String(arr[0].longText || arr[0].shortText || '') : '';
};
const route    = comp('route');
const streetNo = comp('street_number');
// Faellt route aus, ist der Formularwert die naechstbeste Quelle — er ist in
// Modul 5 bereits gegen PLZ und Hausnummer verifiziert.
const streetAddress = route
  ? (streetNo ? route + ' ' + streetNo : route)
  : String(g.strasse || '');

const googlePlace = {
  id: String(P.id || ''),
  displayName: placeDisplayName,
  formattedAddress: String(P.formattedAddress || ''),
  location: {
    lat: (typeof loc.latitude === 'number') ? loc.latitude : 0,
    lng: (typeof loc.longitude === 'number') ? loc.longitude : 0
  }
};
if (!googlePlace.id || !googlePlace.formattedAddress) {
  return fail('Places-Details liefern keine vollständigen Pflichtwerte (id / formattedAddress).');
}

// ── 9 · Kontakt & Socials ────────────────────────────────────────────────
const handleFrom = (url) => {
  let u = String(url || '').trim();
  if (!u) return '';
  u = u.split('?')[0].split('#')[0].replace(/\/+$/, '');
  const parts = u.split('/');
  return String(parts[parts.length - 1] || '').replace(/^@/, '');
};

const e164 = (v) => {
  const raw = String(v || '').trim();
  if (!raw) return '';
  let d = raw.replace(/[^0-9+]/g, '');
  if (!d) return '';
  if (d.charAt(0) === '+') return d;
  if (d.indexOf('00') === 0) return '+' + d.substring(2);
  if (d.charAt(0) === '0')   return '+49' + d.substring(1);
  return '+' + d;
};

// Places hat Vorrang, Formularwert ist Fallback
let phone = String(P.nationalPhoneNumber || '').trim() || g.telefon;
if (phone.length < 7 || phone.length > 25) phone = '';

let website = String(P.websiteUri || '').trim() || g.webseite;
if (!/^https?:\/\//i.test(website)) website = '';

// ── 10 · Metaobjekt-Felder (ohne image/district — kommen in Modul 21) ────

// Teaser-Bild: Dateiname und Alt-Text nach der Konvention des Bestands.
//   Dateiname (slugifiziert): teaser-store-<stadt>-<n>, OHNE Endung.
//   Alt-Text (Klartext):      <n> <Stadtteil> <Stadt>
// Die Endung wird bewusst NICHT mitgegeben: Shopify prueft eine angegebene
// Endung gegen die Quelle, und die Airtable-Anhang-URL endet auf einen Token
// ohne Endung — jede Angabe scheitert dann mit "Provided filename extension
// must match original source". Ohne Endung haengt Shopify die korrekte selbst
// an (am 05.08.2026 gegen den echten Anhang verifiziert: .jpg).
const teaserFilename = 'teaser-store-' + slug(locality) + '-' + slug(g.name);
const teaserAlt = [g.name, locality, districtAirtableName]
  .filter(Boolean).join(' ');
const fields = [];
const put = (key, value) => {
  if (value === '' || value === null || value === undefined) return;
  fields.push({ key: key, value: String(value) });
};

put('name', g.name);
put('assortment_list', JSON.stringify(assortmentGids));
put('rating_count', String(ratingCount));
put('adress', streetAddress);
put('postal_code', String(g.plzInt));
put('city', cityGid);
put('google_place', JSON.stringify(googlePlace));
put('opening_hours', JSON.stringify(openingHours));
put('new', 'true');

if (writeRating) {
  put('rating', JSON.stringify({
    value: String(ratingVal), scale_min: '1.0', scale_max: '5.0'
  }));
}
if (serviceGids.length) put('service_list', JSON.stringify(serviceGids));
if (highlights.length)  put('highlights', JSON.stringify(highlights));
put('phone', phone);
put('website', website);
put('instagram', handleFrom(g.instagram));
put('facebook',  handleFrom(g.facebook));
put('tiktok',    handleFrom(g.tiktok));
put('whatsapp',  e164(g.whatsapp));

// testimonial_list und featured werden bewusst NIE geschrieben.
// product_list und collection_list bleiben leer.

return {
  ok: true,
  gate: 'go',
  reason: '',

  recordId: g.recordId,
  storeName: g.name,
  placeId: googlePlace.id,
  formattedAddress: googlePlace.formattedAddress,
  adress: streetAddress,

  cityGid: cityGid,
  cityRecordId: cityRecordId,
  cityChatId: cityChatId,
  locality: locality,

  // Fuer die Broadcast-Caption (Modul 28). ratingValue ist null, wenn Google
  // keine Bewertung liefert — dieselbe Quelle, aus der weiter unten auch das
  // rating-Feld des Metaobjekts gefuellt wird.
  ratingValue: ratingVal,
  ratingCount: ratingCount,

  districtHandle: districtHandle,
  districtDisplayName: districtDisplayName,
  districtExisted: districtExisted,
  districtRecordId: districtRecordId,

  // Steuerung fuer Modul 39 (Stadtteil find-or-create in Airtable)
  districtApiMethod: districtApiMethod,
  districtApiUrl: districtApiUrl,
  districtApiBody: districtApiBody,
  districtWriteName: districtAirtableName,
  // String statt Boolean — Make reicht Booleans zwischen Modulen nicht
  // zuverlaessig typtreu durch, das Szenario nutzt ueberall 'yes'/'no'.
  districtIsNew: districtExistedAt ? 'no' : 'yes',

  bildUrl: g.bildUrl,
  bildHinweise: g.bildHinweise,
  storeFields: JSON.stringify(fields),
  openingHours: JSON.stringify(openingHours),

  // Fertige GraphQL-Variablen — so muss kein JSON per IML zusammengeklebt werden.
  // Dateiname nach Bestandskonvention, ohne Endung (siehe oben).
  // duplicateResolutionMode REPLACE haelt Wiederholungslaeufe auf EINER Datei,
  // statt bei jedem Versuch eine weitere anzulegen.
  fileVariables: JSON.stringify({
    files: [{
      originalSource: g.bildUrl,
      contentType: 'IMAGE',
      filename: teaserFilename,
      alt: teaserAlt,
      duplicateResolutionMode: 'REPLACE'
    }]
  }),
  districtVariables: JSON.stringify({
    handle: { type: 'liftr_district', handle: districtHandle },
    metaobject: {
      fields: [
        { key: 'name', value: districtDisplayName },
        { key: 'city', value: cityGid }
      ],
      capabilities: { publishable: { status: 'ACTIVE' } }
    }
  }),

  // Lexware
  lexStreet: g.strasse,
  lexZip: g.plz5,
  lexCity: locality
};

