// ── Modul 40 · Bild-Ergebnis pruefen ─────────────────────────────────────
// Steht bewusst ZWISCHEN Modul 19 (fileCreate) und Modul 20 (District-Upsert).
//
// Grund: fileCreate meldet Fehler als GraphQL userErrors, nicht als HTTP-Fehler.
// Modul 19 laeuft deshalb gruen durch, auch wenn kein MediaImage entstanden ist.
// Bis 05.08.2026 fiel das erst in Modul 21 auf — also NACH dem District-Upsert:
// der Bezirk war da bereits angelegt, der Lauf brach ab, und weil ein Throw in
// einem Code-Modul keinen der GATE-Fehlerpfade ausloest, gab es weder eine
// Telegram- noch eine Airtable-Meldung. Zurueck blieb ein verwaister Bezirk,
// von dem niemand erfuhr.
//
// Das Bild ist die einzige merchant-gelieferte Nutzlast in Phase B und damit
// der wahrscheinlichste Abbruchgrund ueberhaupt. Diese Pruefung gehoert deshalb
// vor den ersten Write, nicht dahinter.

const parse = (v) => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);

const fileBody = parse(input.fileBody) || {};

const dig = (obj, path) => {
  let cur = obj;
  for (let i = 0; i < path.length; i++) {
    if (cur === null || cur === undefined) return null;
    cur = cur[path[i]];
  }
  return (cur === undefined) ? null : cur;
};

const errText = (arr) =>
  (arr || []).map((e) => (e.field ? e.field.join('.') + ': ' : '') + e.message).join(' | ');

const fileErrors = dig(fileBody, ['data', 'fileCreate', 'userErrors']) || [];
if (fileErrors.length) throw new Error('fileCreate userErrors: ' + errText(fileErrors));

const files = dig(fileBody, ['data', 'fileCreate', 'files']) || [];
const imageGid = files.length ? String(files[0].id || '') : '';
if (!imageGid) throw new Error('fileCreate hat kein MediaImage zurückgegeben.');

return {
  imageGid: imageGid,
  fileStatus: files.length ? String(files[0].fileStatus || '') : ''
};

