// ── Modul 21 · Store-Payload finalisieren ────────────────────────────────
// Setzt die beiden GIDs ein, die erst in Phase B entstehen: das MediaImage
// (bereits von Modul 40 geprueft) und das liftr_district aus dem Upsert.
// Ergebnis ist der fertige variables-String fuer metaobjectCreate.
//
// Die fileCreate-Pruefung sass frueher hier — sie ist am 05.08.2026 nach
// Modul 40 gewandert, damit sie VOR dem District-Upsert greift (siehe dort).
// Uebrig bleibt hier die District-Pruefung: die kann nur anschlagen, wenn
// Modul 20 selbst fehlschlug, und dann existiert auch kein Bezirk.

const parse = (v) => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);

const fields   = parse(input.fields) || [];
const distBody = parse(input.distBody) || {};
const imageGid = String(input.imageGid || '');

const dig = (obj, path) => {
  let cur = obj;
  for (let i = 0; i < path.length; i++) {
    if (cur === null || cur === undefined) return null;
    cur = cur[path[i]];
  }
  return (cur === undefined) ? null : cur;
};

const errText = (arr) =>
  (arr || []).map((e) => (e.field ? e.field.join('.') + ': ' : '') + e.message).join(' | ');

// ── Bild ────────────────────────────────────────────────────────────────
if (!imageGid) throw new Error('Modul 40 hat keine imageGid geliefert.');

// ── Stadtteil ───────────────────────────────────────────────────────────
const distErrors = dig(distBody, ['data', 'metaobjectUpsert', 'userErrors']) || [];
if (distErrors.length) throw new Error('liftr_district upsert userErrors: ' + errText(distErrors));

const districtGid = String(dig(distBody, ['data', 'metaobjectUpsert', 'metaobject', 'id']) || '');
if (!districtGid) throw new Error('liftr_district: kein GID aus dem Upsert erhalten.');

// ── Zusammensetzen ──────────────────────────────────────────────────────
const all = fields.slice();
all.push({ key: 'image', value: imageGid });
all.push({ key: 'district', value: districtGid });

const variables = {
  metaobject: {
    type: 'liftr_store',
    fields: all
  }
};

return {
  imageGid: imageGid,
  districtGid: districtGid,
  variables: JSON.stringify(variables)
};

