mapper.codeEditorJavascript:
// ── Modul 28 · Broadcast-Caption + Statuszeile ───────────────────────────
// Baut die 🎉-Caption fuer den City-Channel und die Statuszeile fuers
// Operations-Topic. Der Broadcast ist best effort: fehlt Channel oder
// CDN-URL, wird "broadcast" auf "no" gesetzt und nur der Status gepostet.

const parse = (v) => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);

const m        = parse(input.m) || {};
const storeBody = parse(input.storeBody) || {};
const fileBody  = parse(input.fileBody) || {};
const oh        = parse(input.openingHours) || { regular: null };
const lexId     = String(input.lexId || '');

const dig = (obj, path) => {
  let cur = obj;
  for (let i = 0; i < path.length; i++) {
    if (cur === null || cur === undefined) return null;
    cur = cur[path[i]];
  }
  return (cur === undefined) ? null : cur;
};

const storeGid    = String(dig(storeBody, ['data', 'metaobjectCreate', 'metaobject', 'id']) || '');
const storeHandle = String(dig(storeBody, ['data', 'metaobjectCreate', 'metaobject', 'handle']) || '');

// CDN-URL des MediaImage (kann beim ersten Poll noch fehlen)
let photoUrl = String(dig(fileBody, ['data', 'node', 'image', 'url']) || '');
const fileStatus = String(dig(fileBody, ['data', 'node', 'fileStatus']) || '');

const esc = (v) => String(v || '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ── Oeffnungszeiten: Minutenraster -> Tageslabels -> Spannen ─────────────
const DAY_ORDER  = [1, 2, 3, 4, 5, 6, 0];              // Mo..So
const DAY_LABEL  = { 0: 'So', 1: 'Mo', 2: 'Di', 3: 'Mi', 4: 'Do', 5: 'Fr', 6: 'Sa' };
const periods = (oh.regular && oh.regular.periods) ? oh.regular.periods : [];

const grid = [];
for (let d = 0; d < 7; d++) { grid.push(new Array(1440).fill(false)); }

const mark = (day, from, to) => {                       // to exklusiv
  for (let i = from; i < to; i++) grid[day][i] = true;
};

let anyPeriod = false;
for (let i = 0; i < periods.length; i++) {
  const p = periods[i];
  if (!p.open) continue;
  anyPeriod = true;
  if (!p.close) { for (let d = 0; d < 7; d++) mark(d, 0, 1440); continue; }

  let day = p.open.day;
  let cur = (p.open.hour || 0) * 60 + (p.open.minute || 0);
  const endDay = p.close.day;
  const endMin = (p.close.hour || 0) * 60 + (p.close.minute || 0);

  for (let guard = 0; guard < 8; guard++) {
    if (day === endDay && (cur < endMin || (cur === 0 && endMin === 0 && guard > 0))) {
      mark(day, cur, endMin === 0 ? 1440 : endMin);
      break;
    }
    mark(day, cur, 1440);
    day = (day + 1) % 7;
    cur = 0;
    if (day === endDay) { mark(day, 0, endMin); break; }
  }
}

const hhmm = (min) => {
  const h = Math.floor(min / 60), m2 = min % 60;
  return (h < 10 ? '0' : '') + h + ':' + (m2 < 10 ? '0' : '') + m2;
};

const intervalsOf = (day) => {
  const out = [];
  let start = -1;
  for (let i = 0; i < 1440; i++) {
    if (grid[day][i] && start < 0) start = i;
    if (!grid[day][i] && start >= 0) { out.push([start, i]); start = -1; }
  }
  if (start >= 0) out.push([start, 1440]);
  return out;
};

const fmtDay = (d, iv) => {
  if (!iv.length) return 'geschlossen';
  if (iv.length === 1 && iv[0][0] === 0 && iv[0][1] === 1440) return 'durchgehend';
  const next = (d + 1) % 7;
  const ivNext = intervalsOf(next);
  const nextFull = ivNext.length === 1 && ivNext[0][0] === 0 && ivNext[0][1] === 1440;
  // Laeuft der Block ueber Mitternacht in einen komplett offenen Folgetag,
  // ist der Tag Teil einer durchgehenden Strecke.
  if (iv[iv.length - 1][1] === 1440 && nextFull) return 'durchgehend';
  return iv.map((seg) => {
    // Endet der Block um Mitternacht und geht am Folgetag weiter -> zusammenziehen
    if (seg[1] === 1440 && ivNext.length && ivNext[0][0] === 0 && ivNext[0][1] < 1440) {
      return hhmm(seg[0]) + '–' + hhmm(ivNext[0][1]);
    }
    return hhmm(seg[0]) + '–' + hhmm(seg[1] === 1440 ? 1439 : seg[1]);
  }).join(', ');
};

const labels = {};
for (let d = 0; d < 7; d++) labels[d] = fmtDay(d, intervalsOf(d));

// Uebernommene Folgetags-Bloecke am Tagesanfang wieder entfernen
for (let k = 0; k < 7; k++) {
  const d = DAY_ORDER[k];
  const prev = (d + 6) % 7;
  const ivPrev = intervalsOf(prev);
  const ivD = intervalsOf(d);
  if (!ivPrev.length || !ivD.length) continue;
  if (ivPrev[ivPrev.length - 1][1] === 1440 && ivD[0][0] === 0 && ivD[0][1] < 1440) {
    labels[d] = fmtDay(d, ivD.slice(1));
  }
}

// Gleiche Labels zu Spannen zusammenziehen
const spans = [];
for (let k = 0; k < 7; k++) {
  const d = DAY_ORDER[k];
  const last = spans[spans.length - 1];
  if (last && last.label === labels[d]) last.to = d;
  else spans.push({ from: d, to: d, label: labels[d] });
}

const pad = (v, n) => { let x = String(v); while (x.length < n) x += ' '; return x; };
const hoursLines = spans.map((sp) => {
  const head = (sp.from === sp.to)
    ? DAY_LABEL[sp.from]
    : DAY_LABEL[sp.from] + '–' + DAY_LABEL[sp.to];
  return pad(head, 6) + '  ' + sp.label;
});

// ── Caption ─────────────────────────────────────────────────────────────
const mapsLink =
  'https://www.google.com/maps/search/?api=1&query=' +
  encodeURIComponent(m.storeName || '') +
  '&query_place_id=' + encodeURIComponent(m.placeId || '');
const mapsLinkHtml = mapsLink.replace(/&/g, '&amp;');

const lines = [];
// Bestandskonvention aus dem Restock-Post: Headline ist das Typ-Label und
// steht fett, die Meta-Zeile darunter traegt {store_name} · {stadtteil} und
// bleibt mager. Der Store-Name gehoert also NICHT in die Headline.
lines.push('🎉 <b>Neuer Partner</b>');
lines.push(esc(m.storeName) + ' · ' + esc(m.districtDisplayName));
// Bewertung. Faellt weg, wenn Google keine liefert — dieselbe Bedingung, unter
// der Modul 17 auch das rating-Feld des Metaobjekts fuellt. Der Wert ist ein
// Stand vom Anlegetag und wird im Post nie nachgezogen; die laufende Zahl
// steht im Store-Finder.
const ratingValue = (typeof m.ratingValue === 'number') ? m.ratingValue : null;
const ratingCount = (typeof m.ratingCount === 'number') ? m.ratingCount : 0;
if (ratingValue !== null && ratingCount >= 1) {
  const stars = ratingValue.toFixed(1).replace('.', ',');
  const count = String(ratingCount).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  lines.push('');
  lines.push('⭐ ' + stars + ' (' + count +
             (ratingCount === 1 ? ' Google-Rezension)' : ' Google-Rezensionen)'));
}
if (anyPeriod && hoursLines.length) {
  lines.push('');
  lines.push('🕒 <b>Öffnungszeiten</b>');
  for (let i = 0; i < hoursLines.length; i++) lines.push(hoursLines[i]);
}
lines.push('');
lines.push('<a href="' + mapsLinkHtml + '">Google Maps öffnen</a>');

const caption = lines.join('\n');

// ── Broadcast-Entscheidung ──────────────────────────────────────────────
const chatId = String(m.cityChatId || '').trim();
const canBroadcast = !!chatId && !!photoUrl;

const skipReason = !chatId
  ? 'kein Telegram-Channel an der Stadt hinterlegt'
  : (!photoUrl ? 'Shopify-CDN-URL noch nicht verfügbar (fileStatus: ' + (fileStatus || 'unbekannt') + ')' : '');

// ── Statuszeile Operations ──────────────────────────────────────────────
const status = [
  '✅ <b>Store angelegt: ' + esc(m.storeName) + '</b>',
  m.locality + ' · ' + m.districtDisplayName,
  'Shopify: ' + (storeHandle || storeGid || '—'),
  'Lexware: ' + (lexId || '—'),
  'Broadcast: ' + (canBroadcast ? 'gesendet' : 'übersprungen (' + skipReason + ')')
];

// Die JTL-Kundennummer (Stores.ID) setzt das Szenario NICHT — sie kommt aus
// JTL und traegt den Bestands-Schluessel ("S" & Store-Nummer & "-P" &
// Artikelnummer). Ohne sie greifen Restock und Inventory fuer diesen Store
// nicht. Deshalb bei jeder Neuanlage explizit anfordern.
status.push('📋 JTL-Kundennummer in Airtable nachtragen (Feld »ID«) — ' +
            'ohne sie greift der Bestands-Schlüssel nicht.');

// Ein neu angelegter Stadtteil ist der einzige Schritt ohne maschinelle
// Gegenprobe: liegt der Store auf einer Stadtteilgrenze, liefert der Geocoder
// einen plausiblen, aber falschen Bezirk — wohlgeformt und von keiner Pruefung
// fangbar. Einziger Detektor ist die Sichtpruefung, also hier explizit nennen.
if (String(m.districtIsNew || '') === 'yes') {
  status.push('⚠️ Stadtteil neu angelegt: ' + esc(m.districtDisplayName) +
              ' — bitte prüfen, ob das der richtige ist.');
}

// Weiche Bildhinweise aus Modul 2 (zu schmal, Hochformat). Sie haben den Lauf
// bewusst nicht gestoppt — der Store steht, das Bild ist nur nicht optimal.
// Nachbessern heisst: in Airtable ein besseres Bild setzen und das Teaser-Bild
// neu ziehen, nicht den Store neu anlegen.
if (String(m.bildHinweise || '') !== '') {
  status.push('🖼️ ' + esc(String(m.bildHinweise)));
}

// Nutzlast fuer die Klingel an [Dispatch] Telegram Notifications. Der
// Oeffnungszeiten-Block kommt aus Google Places und steht nirgends in
// Airtable — er muss deshalb als ctx mit. Alles Store-Gebundene liest der
// Dispatcher selbst.
const klingelCtx = JSON.stringify({
  'Öffnungszeiten': hoursLines.join('\n')
});

return {
  ctx: klingelCtx,
  broadcast: canBroadcast ? 'yes' : 'no',
  chatId: chatId,
  photoUrl: photoUrl,
  caption: caption,
  status: status.join('\n'),
  storeGid: storeGid,
  storeHandle: storeHandle
};

// ctx als fertiger JSON-Text — Fehlermeldungen tragen Anfuehrungszeichen
// und Zeilenumbrueche und wuerden den JSON-Body sonst zerlegen.
return { ctx: JSON.stringify({
  "Store": String(input.store || ''),
  "Stufe": String(input.stufe || ''),
  "Fehler": String(input.fehler || '')
}) };

